def can_partition_k_subsets(nums, k):
    total = sum(nums)
    if total % k != 0:
        return False
    target = total // k
    nums.sort(reverse=True)                          # largest first: fail fast
    if nums[0] > target:
        return False
    n = len(nums)
    used = [False] * n

    def backtrack(start_idx, current_sum, groups_formed):
        if groups_formed == k:
            return True
        if current_sum == target:
            return backtrack(0, 0, groups_formed + 1)   # start a fresh bucket
        for i in range(start_idx, n):
            if used[i] or current_sum + nums[i] > target:
                continue                                  # overflow pruning
            used[i] = True
            if backtrack(i + 1, current_sum + nums[i], groups_formed):
                return True
            used[i] = False
            if current_sum == 0:
                break                                       # empty-bucket fail-fast pruning
        return False

    return backtrack(0, 0, 0)

