import java.util.*;

public class Main {
    static boolean[] used;
    static int target, n;

    static boolean canPartitionKSubsets(int[] numsIn, int k) {
        int[] nums = numsIn.clone();
        int total = 0;
        for (int x : nums) total += x;
        if (total % k != 0) return false;
        target = total / k;
        Arrays.sort(nums);
        for (int i = 0, j = nums.length - 1; i < j; i++, j--) { int t = nums[i]; nums[i] = nums[j]; nums[j] = t; }  // descending
        if (nums[0] > target) return false;
        n = nums.length;
        used = new boolean[n];
        return backtrack(nums, 0, 0, 0, k);
    }

    static boolean backtrack(int[] nums, int startIdx, int currentSum, int groupsFormed, int k) {
        if (groupsFormed == k) return true;
        if (currentSum == target) return backtrack(nums, 0, 0, groupsFormed + 1, k);   // fresh bucket
        for (int i = startIdx; i < n; i++) {
            if (used[i] || currentSum + nums[i] > target) continue;    // overflow pruning
            used[i] = true;
            if (backtrack(nums, i + 1, currentSum + nums[i], groupsFormed, k)) return true;
            used[i] = false;
            if (currentSum == 0) break;                                  // empty-bucket fail-fast
        }
        return false;
    }
}

